// REALCHECK-837: Figma RealChecker file, Ready for Dev page, mobile frames -> Lokalise screenshots on the 13 batch keys (Realchecker FE)
const project_id = '964775386a3ce03ecca883.03770715';
const only = [];
const shots = [
  { url: 'https://www.figma.com/api/mcp/asset/f653db8a-643d-48b3-8808-3cf9afdd6ccf.png', title: 'REALCHECK-837 – Forgot password pop-up', description: 'Forgot-password pop-up (mobile). This design still shows the OLD copy ("Enter your email and we will send your password." / "Send password"). In the app the text under the title is now "Enter your email and we will send you a link to reset your password." and the button is "Send link".', key_ids: [987959191, 987959192], tags: ['REALCHECK-837'] },
  { url: 'https://www.figma.com/api/mcp/asset/759221cd-9e93-472b-99fa-2c49f9ee9622.png', title: 'REALCHECK-837 – Check your email', description: 'Confirmation in the forgot-password pop-up after "Send link": title, then line_1 + the user email address (on its own line, bold) + line_2, a grey note box (line_3) and the Done button.', key_ids: [987959193, 987959194, 987959195, 987959196], tags: ['REALCHECK-837'] },
  { url: 'https://www.figma.com/api/mcp/asset/e632d760-df34-4cf8-b4a4-605622520bed.png', title: 'REALCHECK-837 – Choose a new password', description: 'Page opened from the link in the password reset email (mobile): title, text, two password fields and the Save password button.', key_ids: [987959200, 987959201, 987959202], tags: ['REALCHECK-837'] },
  { url: 'https://www.figma.com/api/mcp/asset/762dd08c-f76b-48bd-b7ee-280c52c87dae.png', title: 'REALCHECK-837 – Password saved, log in', description: 'Same page when the new password was saved but the automatic login failed: info box "Your password was saved. Log in with your new password." with a Log in button below.', key_ids: [987959203], tags: ['REALCHECK-837'] },
  { url: 'https://www.figma.com/api/mcp/asset/b84451c8-f5f8-48c9-bb35-cca5a0e35de9.png', title: 'REALCHECK-837 – Link has expired', description: 'Same page when the link is older than 24 hours, already used or broken: title, text and the Send a new link button.', key_ids: [987959197, 987959198, 987959199], tags: ['REALCHECK-837'] }
];
const rows = only.length ? shots.filter(function (s, i) { return only.indexOf(i) >= 0; }) : shots;
return rows.map(function (s) { return { json: Object.assign({ project_id: project_id }, s) }; });

const P = $('Params').all(); const items = $input.all(); const out = [];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const p = P[i].json;
  out.push({ json: { project_id: p.project_id, title: p.title, bytes: buf.length, body: { screenshots: [{ data: 'data:image/png;base64,' + buf.toString('base64'), title: p.title, description: p.description, ocr: false, key_ids: p.key_ids, tags: p.tags || [] }] } } });
}
return out;

const T = $('To Body').all(); const res = $input.all(); const out = [];
for (let i = 0; i < res.length; i++) {
  const r = res[i].json; const b = r.body || {}; const s = (b.screenshots || [])[0] || {};
  out.push({ title: T[i] && T[i].json.title, bytes: T[i] && T[i].json.bytes, http: r.statusCode, screenshot_id: s.screenshot_id, key_ids: s.key_ids, w: s.width, h: s.height, errors: b.errors || b.error || null });
}
return [{ json: { results: out } }];
